import { createLogger } from "./logger.js";
import { createMetricsClient } from "./metrics.js";
import { refundOrder } from "./refunds.js";

export function buildApp() {
  const logger = createLogger({ level: process.env.LOG_LEVEL ?? "info" });
  const metrics = createMetricsClient({
    endpoint: process.env.OTEL_EXPORTER_OTLP_ENDPOINT,
    serviceName: "orders",
  });
  return { logger, metrics, refundOrder: (orderId, gateway) => refundOrder({ gateway, logger, metrics }, orderId) };
}

